using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace Retrace.Engine.Util;

/// <summary>
/// A dialog font at 96 DPI: how Windows converts dialog units to pixels with it and how wide its
/// text is. Widths and ascents come from <c>FontMetricsData</c> (generated by tools/gen_font_metrics.py).
/// </summary>
public sealed class TextFont
{
    public string Name { get; init; } = "MS Shell Dlg";
    public double Pt { get; init; } = 8;
    /// <summary>Key into FontMetricsData: MicrosoftSansSerif, Tahoma, Arial, or SegoeUI (real GDI widths at 11 and 12 px).</summary>
    public string Key { get; init; } = "MicrosoftSansSerif";
    public string Css { get; init; } = "'Microsoft Sans Serif', Tahoma, Arial, sans-serif";
    /// <summary>Pixel height, round(pt * 96 / 72).</summary>
    public int Px { get; init; } = 11;
    /// <summary>Dialog base units (cx, cy) for this font: 1 DLU = cx/4 px horizontally, cy/8 px vertically.</summary>
    public int Cx { get; init; } = 6;
    public int Cy { get; init; } = 13;
    /// <summary>Distance from the top of a text line to its baseline.</summary>
    public int Ascent { get; init; } = 11;

    /// <summary>Horizontal px per DLU.</summary>
    public double Sx => Cx / 4.0;
    /// <summary>Vertical px per DLU.</summary>
    public double Sy => Cy / 8.0;

    private int[]? _w;
    private int _avg = 6;
    private double _scale = 1;

    internal void Init()
    {
        var (w, avg, scale, _) = FontMetrics.Table(Key, Px);
        _w = w; _avg = avg; _scale = scale;
    }

    public double Width(char c)
    {
        if (_w == null) Init();
        if (c >= 32 && c <= 126) return Math.Round(_w![c - 32] * _scale);
        if (c >= 0x2E80) return Px; // CJK and other full-width glyphs
        return Math.Round(_avg * _scale);
    }

    public double Width(string? s)
    {
        if (string.IsNullOrEmpty(s)) return 0;
        double t = 0;
        foreach (var ch in s) t += Width(ch);
        return t;
    }

    /// <summary>Longest prefix that fits maxWidth. No ellipsis: Windows just clips.</summary>
    public string Clip(string? s, double maxWidth)
    {
        s ??= "";
        double t = 0;
        for (int i = 0; i < s.Length; i++)
        {
            t += Width(s[i]);
            if (t > maxWidth) return s[..i];
        }
        return s;
    }

    /// <summary>Greedy word wrap like DrawText: break at spaces only. A word wider than the line stays whole (the caller clips it).</summary>
    public List<string> Wrap(string? text, double width, bool wrap = true)
    {
        var lines = new List<string>();
        foreach (var para in (text ?? "").Split('\n'))
        {
            if (!wrap) { lines.Add(para); continue; }
            var cur = new StringBuilder();
            double curW = 0, space = Width(' ');
            foreach (var word in para.Split(' '))
            {
                double ww = Width(word);
                if (cur.Length > 0 && curW + space + ww <= width) { cur.Append(' ').Append(word); curW += space + ww; continue; }
                if (cur.Length > 0) { lines.Add(cur.ToString()); cur.Clear(); curW = 0; }
                // a word wider than the line is not broken: Windows draws it whole and clips it at the rect edge
                cur.Append(word); curW = ww;
            }
            lines.Add(cur.ToString());
        }
        return lines;
    }
}

/// <summary>
/// Dialog font handling. Dialog base units (cx, cy) were verified against real Windows 11 captures at 96 DPI
/// (dialogBaseUnits in the capture json): Microsoft Sans Serif 8 = (6, 13), MS Sans Serif 8 = (6, 13),
/// Arial 9 = (7, 15). Segoe UI 9 = (7, 15) and Tahoma 8 = (6, 13) are not covered by those captures.
/// </summary>
public static class FontMetrics
{
    // (family names, pt) -> base units (cx, cy) at 96 DPI. Unknown or missing font -> Default (6, 13).
    private static readonly (string[] Names, double Pt, int Cx, int Cy)[] BaseUnits =
    {
        (new[] { "ms shell dlg", "ms shell dlg 2", "ms sans serif", "microsoft sans serif", "tahoma" }, 8, 6, 13),
        (new[] { "segoe ui" }, 9, 7, 15),
        (new[] { "arial" }, 9, 7, 15),
    };

    /// <summary>The Win32 default dialog font: MS Shell Dlg 8.</summary>
    public static TextFont Default { get; } = Make("MS Shell Dlg", 8);

    /// <summary>Segoe UI 9: caption font of Windows 10/11 and the font used for XAML and DCL layouts.</summary>
    public static TextFont SegoeUi9 { get; } = Make("Segoe UI", 9);

    /// <summary>WinForms default font: Microsoft Sans Serif 8.25.</summary>
    public static TextFont WinFormsDefault { get; } = Make("Microsoft Sans Serif", 8.25);

    /// <summary>Parse a FONT line value like "8 MS Shell Dlg" (as stored in UiForm.Extra["font"]).</summary>
    public static TextFont Parse(string? font)
    {
        if (string.IsNullOrWhiteSpace(font)) return Default;
        var m = Rx.Match(font.Trim(), @"^(\d+(?:\.\d+)?)\s+(.+)$");
        if (!m.Success) return Default;
        return Make(m.Groups[2].Value.Trim(), double.Parse(m.Groups[1].Value, CultureInfo.InvariantCulture));
    }

    public static TextFont Make(string name, double pt)
    {
        string n = name.Trim().ToLowerInvariant();
        string key = n switch
        {
            "tahoma" or "ms shell dlg 2" => "Tahoma",
            "segoe ui" => "SegoeUI",
            "arial" => "Arial",
            _ => "MicrosoftSansSerif",
        };
        string css = key switch
        {
            "Tahoma" => "Tahoma, 'Microsoft Sans Serif', Arial, sans-serif",
            "SegoeUI" => "'Segoe UI', Tahoma, Arial, sans-serif",
            "Arial" => "Arial, 'Helvetica Neue', sans-serif",
            _ => "'Microsoft Sans Serif', Tahoma, Arial, sans-serif",
        };
        int cx = 6, cy = 13;
        foreach (var row in BaseUnits)
            if (row.Names.Contains(n) && Math.Abs(row.Pt - pt) < 0.01) { cx = row.Cx; cy = row.Cy; break; }
        int px = (int)Math.Round(pt * 96 / 72, MidpointRounding.AwayFromZero);
        var f = new TextFont
        {
            Name = name, Pt = pt, Key = key, Css = css, Px = px, Cx = cx, Cy = cy,
            Ascent = Table(key, px).Ascent,
        };
        f.Init();
        return f;
    }

    /// <summary>The bold-free caption font (Segoe UI 12 px) used for the title bar.</summary>
    public static TextFont Caption { get; } = Make("Segoe UI", 9);

    // ------------------------------------------------------------ tables

    internal static (int[] Widths, int Avg, double Scale, int Ascent) Table(string key, int px)
    {
        var sizes = FontMetricsData.Tables.Keys.Where(k => k.Font == key).Select(k => k.Ppem).ToList();
        if (sizes.Count == 0) return Table("MicrosoftSansSerif", px);
        int best = sizes.OrderBy(s => Math.Abs(s - px)).First();
        var t = FontMetricsData.Tables[(key, best)];
        double scale = best == px ? 1 : (double)px / best;
        return (t.Widths, t.Avg, scale, (int)Math.Round(t.Ascent * scale));
    }
}
